1	/**
2	 * `linecache`: the module the traceback printer uses to fetch source lines.
3	 *
4	 * Frame filenames are relative (`test14.py`), so they resolve against the
5	 * current working directory -- when the script is run from somewhere else the
6	 * lookup simply fails and the traceback shows no source lines at all.
7	 */
8	
9	import { readFileSync } from 'node:fs';
10	
11	const cache = new Map();
12	
13	/** `readlines()` on a text-mode file: universal newlines, terminators kept. */
14	function splitKeepEnds(text) {
15	  const normalised = text.replace(/\r\n?/g, '\n');
16	  const lines = [];
17	  let start = 0;
18	  for (let index = 0; index < normalised.length; index += 1) {
19	    if (normalised[index] === '\n') {
20	      lines.push(normalised.slice(start, index + 1));
21	      start = index + 1;
22	    }
23	  }
24	  if (start < normalised.length) lines.push(normalised.slice(start));
25	  return lines;
26	}
27	
28	function linesFor(fileName) {
29	  if (cache.has(fileName)) return cache.get(fileName);
30	  let lines;
31	  try {
32	    lines = splitKeepEnds(readFileSync(fileName, 'utf8'));
33	  } catch {
34	    lines = [];
35	  }
36	  cache.set(fileName, lines);
37	  return lines;
38	}
39	
40	/**
41	 * The raw source line, terminator included, or `''` when unavailable.
42	 *
43	 * @param {string} fileName
44	 * @param {number} lineNumber 1 based
45	 * @returns {string}
46	 */
47	export function getLine(fileName, lineNumber) {
48	  const lines = linesFor(fileName);
49	  if (lineNumber < 1 || lineNumber > lines.length) return '';
50	  return lines[lineNumber - 1];
51	}
